import { SPEC_NOTES, SPECS_PAGE, U1 } from "./specs";
import type { Job, Plan, Project, ToolSlot } from "./types";
import { TOOL_SLOTS } from "./types";

export function planToMarkdown(plan: Plan): string {
  const lines: string[] = [];
  lines.push(`# Fourload plan: ${plan.projectName}`);
  lines.push("");
  lines.push(
    "Generated by Fourload. This is a planning aid, not a slice, and it has not been validated on a physical Snapmaker U1. Build volume, toolhead count, temperatures, speed, acceleration, flow, and material lists are taken from official Snapmaker pages cited at the end.",
  );
  lines.push("");

  if (plan.blockedParts.length > 0) {
    lines.push("## Blocked parts");
    lines.push("");
    for (const blocked of plan.blockedParts) {
      lines.push(`- ${blocked.part.name}: ${blocked.reasons.map((reason) => reason.message).join(" ")}`);
    }
    lines.push("");
  }

  if (plan.warnings.length > 0) {
    lines.push("## Plate notes");
    lines.push("");
    for (const warning of plan.warnings) {
      lines.push(`- ${warning.message}`);
    }
    lines.push("");
  }

  for (const job of plan.jobs) {
    lines.push(`## Job ${job.index + 1} of ${plan.jobs.length}`);
    lines.push("");
    lines.push(
      `Bed: ${U1.buildVolumeMm[0]} × ${U1.buildVolumeMm[1]} × ${U1.buildVolumeMm[2]} mm official build volume. Fits: ${job.fitsBed ? "yes" : "no"}.`,
    );
    lines.push("");
    lines.push("| Slot | Colour | Hex |");
    lines.push("| --- | --- | --- |");
    for (const slot of TOOL_SLOTS) {
      const color = job.slots[slot as ToolSlot];
      if (color) lines.push(`| ${slot} | ${color.name} | ${color.hex} |`);
      else lines.push(`| ${slot} | (empty) |  |`);
    }
    lines.push("");
    lines.push("Parts:");
    lines.push("");
    for (const part of job.parts) {
      const [x, y, z] = part.positionMm;
      const [sx, sy, sz] = part.sizeMm;
      const rotation = part.rotatedXy ? ", X and Y swapped for packing" : "";
      const material = part.material ? `, material ${part.material}` : "";
      lines.push(
        `- ${part.name}: ${fmt(sx)} × ${fmt(sy)} × ${fmt(sz)} mm at (${fmt(x)}, ${fmt(y)}, ${fmt(z)})${rotation}${material}`,
      );
    }
    lines.push("");
    if (job.warnings.length > 0) {
      lines.push("Job notes:");
      lines.push("");
      for (const warning of job.warnings) {
        lines.push(`- ${warning.message}`);
      }
      lines.push("");
    }
  }

  lines.push("## Official sources");
  lines.push("");
  lines.push(`- ${SPECS_PAGE.label}: ${SPECS_PAGE.url}`);
  lines.push(`- ${SPEC_NOTES.usableBed.text} Source: ${SPEC_NOTES.usableBed.source.url}`);
  lines.push(`- ${SPEC_NOTES.hotends.text} Source: ${SPEC_NOTES.hotends.source.url}`);
  lines.push(`- ${SPEC_NOTES.swapTime.text} Source: ${SPEC_NOTES.swapTime.source.url}`);
  lines.push(`- ${SPEC_NOTES.maxFlow.text} Source: ${SPEC_NOTES.maxFlow.source.url}`);
  lines.push("");
  lines.push("Fourload is an independent project and is not affiliated with Snapmaker.");
  lines.push("");
  return lines.join("\n");
}

export function planToJson(project: Project, plan: Plan): string {
  return `${JSON.stringify({ project, plan }, null, 2)}\n`;
}

function fmt(n: number): string {
  return Number.isInteger(n) ? String(n) : n.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

export function jobSlotList(job: Job): string {
  return TOOL_SLOTS.map((slot) => {
    const color = job.slots[slot];
    return color ? `${slot} ${color.name}` : `${slot} empty`;
  }).join(", ");
}
